  AND NOT EXISTS (SELECT 1 FROM review_tags x WHERE x.review_id = rt.review_id AND x.tag_id = (SELECT id FROM tags WHERE slug = 'dive_bar'));
DELETE FROM review_tags WHERE tag_id = (SELECT id FROM tags WHERE slug = 'dive-bar');
UPDATE place_tags pt SET tag_id = (SELECT id FROM tags WHERE slug = 'dive_bar') WHERE pt.tag_id = (SELECT id FROM tags WHERE slug = 'dive-bar')
