DELETE FROM place_tags WHERE tag_id = (SELECT id FROM tags WHERE slug = 'dive-bar');
DELETE FROM place_tag_aggregates WHERE tag_id = (SELECT id FROM tags WHERE slug = 'dive-bar');
UPDATE tags SET synonyms = (SELECT array_agg(DISTINCT s) FROM unnest(synonyms || ARRAY['dive bar']) s)
